class Solution {
public:
    long long minimumSteps(string s) {
        long long ans = 0;
        int black_cnt = 0;
        for (char c : s) {
            if (c == '1') black_cnt++;
            else ans += black_cnt;
        }
        return ans;
    }
};

class Solution {
    public long minimumSteps(String s) {
        long ans = 0;
        int blackCnt = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '1') blackCnt++;
            else ans += blackCnt;
        }
        return ans;
    }
}

